//! SMLib's stitching tests (NVIDIA usd-brep `tests/prog_test/src/smMergeTest.cpp`, Apache-2.0; models in
//! `tests/data/smlib/stitch`) on the native kernel. Generated by `tools/smlib_to_rust.py` from
//! `tools/smlib/stitch.py` with SMLib's own results (the oracle); known failures (`tools/smlib_known_failures/stitch.txt`)
//! must still fail.
#![allow(clippy::all)]

mod smlib_common;
#[allow(unused_imports)]
use smlib_common::*;

use cadrs_kernel::native::NativeKernel;
use cadrs_kernel::native::surfacing;
use cadrs_kernel::native::topo::Body;
use cadrs_kernel::{BoolOp, Kernel};

const SUITE: &str = "stitch";

/// Edges used by one face only.
fn lamina(b: &Body) -> usize {
    b.edge_faces()
        .iter()
        .zip(&b.edges)
        .filter(|(f, e)| !e.degenerate && f.len() == 1)
        .count()
}

/// `file`'s faces sewn at `tol` (`StitchFaces`): valid, with at most `max_lamina` lamina edges.
fn stitch_open(file: &str, tol: f64, max_lamina: usize) -> Result<(), String> {
    let b = surfacing::sew_faces(model(SUITE, file)?.body, tol).map_err(|e| format!("{e:?}"))?;
    if let Some(i) = invalid(&b) {
        return Err(i);
    }
    let n = lamina(&b);
    if n > max_lamina {
        return Err(format!("{n} lamina edges, SMLib leaves {max_lamina}"));
    }
    Ok(())
}

/// `file`'s faces sewn at each of `tols` in turn, the last closing a solid (`surfacing::sew`).
fn stitched(k: &mut NativeKernel, file: &str, tols: &[f64]) -> Result<(Body, Body), String> {
    let input = model(SUITE, file)?.body;
    let (last, first) = tols.split_last().ok_or("no tolerances")?;
    let mut b = input.clone();
    for &t in first {
        b = surfacing::sew_faces(b, t).map_err(|e| format!("{e:?}"))?;
    }
    let id = k.insert(b);
    let r = surfacing::sew(k, &[id], *last).map_err(|e| format!("{e:?}"))?;
    let out = (**k.get(r.bodies[0]).map_err(|e| format!("{e:?}"))?).clone();
    Ok((input, out))
}

/// Stitched at `tols`: no lamina edges, a valid closed solid with SMLib's values `e`.
fn stitch_closed(file: &str, tols: &[f64], e: &Expect) -> Result<(), String> {
    let mut k = NativeKernel::new();
    let (input, out) = stitched(&mut k, file, tols)?;
    let n = lamina(&out);
    if n > 0 {
        return Err(format!("{n} lamina edges"));
    }
    check_result(&input, &out, e)
}

/// `file` reads as a valid solid.
fn read_solid(file: &str) -> Result<(), String> {
    let b = model(SUITE, file)?.body;
    check_result(&b, &b, &Expect::default())
}

/// The part stitched at `tols`, less `tool`.
fn stitch_then_cut(file: &str, tols: &[f64], tool: &str) -> Result<(), String> {
    let mut k = NativeKernel::new();
    let (_, part) = stitched(&mut k, file, tols)?;
    let cut = model(SUITE, tool)?.body;
    let (vp, vc) = (
        cadrs_kernel::native::mass::body_mass(&part).volume,
        cadrs_kernel::native::mass::body_mass(&cut).volume,
    );
    let (a, b) = (k.insert(part.clone()), k.insert(cut));
    let r = k
        .boolean(BoolOp::Subtract, a, &[b])
        .map_err(|e| format!("{e:?}"))?;
    let [one] = r.bodies.as_slice() else {
        return Err(format!("{} bodies", r.bodies.len()));
    };
    let out = (**k.get(*one).map_err(|e| format!("{e:?}"))?).clone();
    check_result(&part, &out, &Expect::default())?;
    let v = cadrs_kernel::native::mass::body_mass(&out).volume;
    if !(v >= vp - vc - 1e-6 * vp && v < vp) {
        return Err(format!(
            "volume {v:.6}: not between the part's less the cylinder's ({:.6}) and the part's ({vp:.6})",
            vp - vc
        ));
    }
    Ok(())
}

/// SMLib stitching 1: `fillet_ts.smb` stitched at 0.001 (SMLib leaves 4 lamina edges).
#[test]
fn stitch_1_fillet_ts_0001() {
    stitch_open("fillet_ts.smb", 0.001, 4).unwrap();
}

/// SMLib stitching 2: `fillet_ts.smb` stitched at 0.001 then 0.005: closed, SMLib's volume 924.828575 and area 605.235965.
#[test]
fn stitch_2_fillet_ts_0005() {
    stitch_closed(
        "fillet_ts.smb",
        &[0.001, 0.005],
        &Expect {
            volume: Some(924.82857533),
            area: Some(605.235964878),
            solid: Some(true),
            ..Expect::default()
        },
    )
    .unwrap();
}

/// SMLib stitching 3: `fillet_cut.smb` (the cylinder cut from the stitched part) reads as a solid.
#[test]
fn stitch_3_read_fillet_cut() {
    read_solid("fillet_cut.smb").unwrap();
}

/// SMLib stitching 4: the stitched `fillet_ts.smb` less `fillet_cut.smb` (`my_two_prim_test`).
#[test]
fn stitch_4_cut() {
    known_failure(
        stitch_then_cut("fillet_ts.smb", &[0.001, 0.005], "fillet_cut.smb"),
        "stitch",
        "stitch_4_cut",
    );
}
